        for recipient in ("", "[EMAIL_REMOVIDO],[EMAIL_REMOVIDO]", "A <[EMAIL_REMOVIDO]>", "[EMAIL_REMOVIDO]\r\nBcc:[EMAIL_REMOVIDO]"):
            with self.assertRaises(ServiceError):
